  width: number;
  /** 原图高度（像素） */
  height: number;
  /**
   * 定位点（原图像素坐标）。
   *
   * - 标准二维码：三个定位图案中心，部分版本还会附带对齐图案中心；
   * - 抖音码：作品分享码返回中心圆盘圆心，名片码返回三个圆形定位标记的中心。
   */
